code.cpp:
class Solution {
public:
    long long maximumSubsequenceCount(string text, string pattern) {
        long long existing = 0;
        long long count0 = 0, count1 = 0;
        char p0 = pattern[0], p1 = pattern[1];

        for (char c : text) {
            if (c == p1) {
                existing += count0;
                count1++;
            }
            if (c == p0) {
                count0++;
            }
        }

        return existing + max(count0, count1);
    }
};
